(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.03-t*0.15)*8 + Math.cos(sy*0.025+t*0.2)*6;
  const w2y = Math.cos(sx*0.025+t*0.18)*8 + Math.sin(sy*0.03-t*0.22)*6;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [60+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*40,0.14,1.3,0.8],
    [420+Math.cos(t*0.55+1)*60,220+Math.sin(t*0.75+4)*30,0.11,1.8,1.15],
    [200+Math.sin(t*0.7+2)*50,30+Math.cos(t*0.5+3)*60,0.09,2.1,0.9],
    [300+Math.cos(t*0.4+5)*80,100+Math.sin(t*0.6+1)*70,0.07,2.4,1.0]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    wS+=w;
  }
  const act=aS/wS,inh=iS/wS;
  const bg=(Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1)+Math.sin(wx*0.08+wy*0.06-t*1.5)*0.5+Math.sin(wx*0.12-wy*0.08+t*2)*0.3)/3+Math.sin((wx+wy)*0.12+t*2.5)*0.2+Math.sin((wx-wy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2),ang=Math.atan2(wy-cy,wx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*5+t*0.8)*0.5+Math.sin(dist*0.03+ang*2+t)*0.4)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const c1=Math.sin(wx*0.15)*Math.sin(wy*0.15),c2=Math.sin(wx*0.22+0.5)*Math.sin(wy*0.22+0.5)*0.5;
  const cell=Math.tanh((c1+c2+Math.sin((wx+wy)*0.1+t)*0.5)*1.5)*0.3;
  const caustic=Math.max(0,Math.sin(wx*0.2+wy*0.15+t*1.2)*Math.sin(wx*0.15-wy*0.2-t*0.9))**2*0.15;
  const pulse=1+Math.sin(t*0.8)*0.08;
  const blend=reaction*0.65+cell*0.2+caustic*0.15;
  const v=blend*0.5+0.5;
  const pal=[[5,12,45],[12,40,82],[18,75,120],[25,130,130],[50,165,120],[140,185,80],[210,190,60],[220,140,55],[200,90,60],[160,55,70],[100,30,65],[50,18,55],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.7?1.2:1.0;
  const sparkle=caustic>0.08?1.12:1.0;
  const m=lum*edge*sparkle*pulse;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0];
}
